        "f" + i,
        { skin: skin[(i * 3 + 1) % skin.length], hair: hair[i % hair.length], hairStyle: i % 2 ? "buzz" : "short", top, sleeve: i % 4 === 1 ? "short" : "long" },
        (a, p) => addCap(p, mats, mats.navy)
