    const pz2 = z0 / ab[1];
    const qx = dx / ab[0];
    const qz = dz / ab[1];
    const A = qx * qx + qz * qz;
    const B = 2 * (px2 * qx + pz2 * qz);
    const C = px2 * px2 + pz2 * pz2 - 1;
    return (-B + Math.sqrt(B * B - 4 * A * C)) / (2 * A);
