    const ropePts = [];
    for (let k = 0; k < 96; k++) ropePts.push(ellPt(k / 96 * Math.PI * 2, OVAL.rope, 0.05));
    const rope = new Mesh(new TubeGeometry(new CatmullRomCurve3(ropePts, true), 240, 0.05, 5, true), mats.boardText);
    rope.castShadow = true;
    g.add(rope);
    const colours = [mats.boardBlue, mats.boardNavy, mats.boardYellow, mats.boardOrange];
    const [ba, bb] = OVAL.boards;
    const per = Math.PI * (3 * (ba + bb) - Math.sqrt((3 * ba + bb) * (ba + 3 * bb)));
    const nSeg = Math.round(per / 2.4);
    const gateTh = Math.atan2(GATE_PT.z / bb, (GATE_PT.x - OVAL.cx) / ba);
    for (let k = 0; k < nSeg; k++) {
      const th0 = k / nSeg * Math.PI * 2;
      const th1 = (k + 1) / nSeg * Math.PI * 2;
      const thm = (th0 + th1) / 2;
      let dg = Math.abs((thm - gateTh + Math.PI * 3) % (Math.PI * 2) - Math.PI);
      if (dg < 0.09) continue;
      const a = ellPt(th0, OVAL.boards);
      const b = ellPt(th1, OVAL.boards);
      const mid2 = a.clone().add(b).multiplyScalar(0.5);
      const len = a.distanceTo(b) - 0.06;
      const yaw = -Math.atan2(b.z - a.z, b.x - a.x);
      const mat = colours[k % colours.length];
      const seg = new Group();
      seg.position.copy(mid2);
      seg.rotation.y = yaw;
      g.add(seg);
      box5(seg, len, 0.72, 0.1, mat, 0, 0.36, 0, { r: 0.02 });
      const inward = new Vector3(OVAL.cx, 0, 0).sub(mid2).normalize();
      const localZ = new Vector3(0, 0, 1).applyAxisAngle(new Vector3(0, 1, 0), yaw);
      const s = Math.sign(inward.dot(localZ)) || 1;
      box5(seg, len * 0.62, 0.16, 0.02, mat === mats.boardYellow ? mats.boardNavy : mats.boardText, 0, 0.4, 0.055 * s, { castShadow: false });
    }
    const gp = ellPt(gateTh, OVAL.boards);
    const tang = new Vector3(-ba * Math.sin(gateTh), 0, bb * Math.cos(gateTh)).normalize();
    for (const s of [-1, 1]) {
      const p = gp.clone().addScaledVector(tang, s * 1.9);
      box5(g, 0.14, 1.15, 0.14, mats.whites, p.x, 0.575, p.z, { r: 0.02 });
      box5(g, 0.18, 0.06, 0.18, mats.whites, p.x, 1.18, p.z, { r: 0.02 });
    }
    const leaf = new Group();
    leaf.position.copy(gp.clone().addScaledVector(tang, -1.8));
    leaf.rotation.y = -Math.atan2(tang.z, tang.x) - 1.1;
    g.add(leaf);
    for (let k = 0; k < 6; k++) box5(leaf, 0.06, 0.85, 0.035, mats.whites, 0.12 + k * 0.17, 0.48, 0, { r: 0.01 });
    for (const y of [0.3, 0.72]) box5(leaf, 1.05, 0.06, 0.04, mats.whites, 0.55, y, -0.02, { r: 0.01 });
