    ss.position.set(-24.6, 0, 0.3);
    g.add(ss);
    box5(ss, 0.18, 2.1, 6.2, mats.whites, 0, 1.25, 0, { r: 0.03 });
    for (const z of [-2.6, 0, 2.6]) box5(ss, 0.3, 0.2, 0.3, mats.woodDark, 0, 0.1, z);
