          const tl = sh.timing.toLowerCase().replace(" ", "-");
          const cls = sh.timing === "PERFECT" ? "perfect" : sh.timing.startsWith("VERY") ? "very" : tl;
          const ms = Math.round(sh.err * 1e3);
